package in.foodcart.data;
import in.foodcart.domain.OrderStatus; import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.index.CompoundIndex; import org.springframework.data.mongodb.core.mapping.Document; import java.math.BigDecimal; import java.time.Instant; import java.util.*;
@Document("orders") @CompoundIndex(name="vendor_created",def="{'vendorId':1,'createdAt':-1}") @CompoundIndex(name="customer_created",def="{'customerId':1,'createdAt':-1}") public class OrderEntity { @Id public String id; public long orderNumber; public String vendorId,customerId,customerMobile,type,dineInNote,paymentMethod="CASH",rejectionReason,rejectionNote; public OrderStatus status=OrderStatus.PLACED; public List<Item> items=new ArrayList<>(); public BigDecimal subtotal,total; public Instant createdAt=Instant.now(),acceptedAt,preparingAt,readyAt,completedAt,rejectedAt; public static class Item { public String menuItemId,name,portion="FULL",summary; public BigDecimal price,lineTotal; public int quantity; } }
